 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Continue each diagonal run of a non-background color upward to the edge.
    colors = {v for row in grid for v in row}
    for color in colors:
        starts = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color:
                    continue
                # A run's upper endpoint has no same-colored neighbor above it
                # on either diagonal.
                if not any(0 <= c-dc < w and r > 0 and grid[r-1][c-dc] == color
                           for dc in (-1, 1)):
                    if any(0 <= r+1 < h and 0 <= c+dc < w and grid[r+1][c+dc] == color
                           for dc in (-1, 1)):
                        starts.append((r, c))
        for r, c in starts:
            for dc in (-1, 1):
                if r+1 < h and 0 <= c+dc < w and grid[r+1][c+dc] == color:
                    rr, cc = r, c
                    while rr > 0 and 0 <= cc-dc < w:
                        rr -= 1
                        cc -= dc
                        out[rr][cc] = color
    return out
