 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    freq = {}
    for row in grid:
        for x in row:
            freq[x] = freq.get(x, 0) + 1
    bg = max(freq, key=freq.get)
    # Extend diagonal chains away from their neighboring blocker/boundary.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, -1), (1, 1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color):
                    continue
                # Extend from this pair's end, if its forward cell is blocked
                # or outside; otherwise extend backward if blocked at forward end.
                for sr, sc, start_r, start_c in ((dr, dc, rr, cc), (-dr, -dc, r, c)):
                    nr, nc = start_r + sr, start_c + sc
                    if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != bg:
                        # walk from the chain endpoint in this direction, through background
                        pr, pc = start_r, start_c
                        while 0 <= pr + sr < h and 0 <= pc + sc < w and grid[pr + sr][pc + sc] == color:
                            pr += sr
                            pc += sc
                        nr, nc = pr + sr, pc + sc
                        while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg:
                            out[nr][nc] = color
                            nr += sr
                            nc += sc
    return out
"
